const companies = [
  { name: 'Stripe', website: 'stripe.com', founded: 2010 },
  { name: 'Notion', website: 'notion.so', founded: 2016 },
  { name: 'Vercel', website: 'vercel.com', founded: 2015 },
  { name: 'Supabase', website: 'supabase.com', founded: 2020 },
  { name: 'Hugging Face', website: 'huggingface.co', founded: 2016 }
];

return companies.map(c => ({ json: c }));

// Process all enriched items and merge with original company data
const items = $input.all();
const companyItems = $('Sample Company List').all();

return items.map((item, i) => {
  const raw = item.json.output
            || item.json.text
            || item.json.response
            || item.json.message?.content
            || item.json.content
            || '';
  const company = companyItems[i]?.json || {};

  let enrichment;
  try {
    const cleaned = String(raw).replace(/```(?:json)?\n?/g, '').replace(/```$/g, '').trim();
    enrichment = JSON.parse(cleaned);
  } catch (e) {
    enrichment = { error: 'parse_failed', raw: String(raw).substring(0, 300) };
  }

  return { json: { ...company, ...enrichment, enriched_at: new Date().toISOString() } };
});

// Collect all enriched items into a final report
const items = $input.all();

const report = {
  total_companies: items.length,
  processed_at: new Date().toISOString(),
  companies: items.map(i => i.json)
};

console.log('Enrichment complete:', JSON.stringify(report, null, 2));
return [{ json: report }];
